// Fifth edition (2024 rules) player options, generated by `scripts/dnd5e-data.ts`. Two kinds of
// record, told apart by `srd` (see `data/dnd5e/NOTICE.md` and the rpg-rules skill's
// licensing.md):
// - `srd: true`: an entry of the SRD 5.2.1 (CC-BY-4.0). It keeps the SRD's text (`text`) and
//   cites the SRD page.
// - `srd: false`: an option from an official book the SRD leaves out (the Player's Handbook
//   (2024) and the later books in `./sources`). It has no book text, only its mechanics as fields
//   and a short `summary` written for Lantern.
// Both carry the structured fields the builder, level-up and play engine read, so code never
// has to parse rules prose. Book art is never included.
import type { Dnd5eAbility } from '~/types/sheets'
import type { Dnd5eSourceBook } from './sources'

export type { Dnd5eAbility, Dnd5eSourceBook }

export interface Dnd5eRecord {
  /** Unique within its set, kebab-case (`fireball`, `battle-master`). */
  slug: string
  name: string
  srd: boolean
  /** The book whose version this is: the latest that prints it (see `./sources`). */
  source: Dnd5eSourceBook
  /** Every book that prints it, oldest first, when more than one does (a reprint). */
  sources?: Dnd5eSourceBook[]
  /** SRD 5.2.1 printed page (the PDF's page numbers match); SRD entries only. */
  page?: number
  /** The SRD's rules text as markdown; SRD entries only. */
  text?: string
  /**
   * A one-line description: every entry has one. A non-SRD entry's is written in Lantern's own
   * words (it is all the prose such an entry carries); an SRD entry's is drawn from its text.
   */
  summary?: string
  /** The dnd2024.wikidot.com page it was checked against (`spell:fireball`), for non-SRD entries. */
  wiki?: string
}

/** How long until uses come back; `short` is a Short or Long Rest. */
export type Dnd5eRecharge = 'turn' | 'short' | 'long' | 'dawn'

/**
 * A use limit. `count` is a number, `PB` (Proficiency Bonus), an ability (its modifier,
 * minimum 1), `column:<name>` (a column of the class table, like `column:Rages`) or
 * `level` (class level). `short` on a `long` recharge: uses a Short Rest gives back.
 */
export interface Dnd5eUses {
  count: number | 'PB' | 'level' | Dnd5eAbility | `column:${string}`
  recharge: Dnd5eRecharge
  short?: number | 'all'
  /** What else restores a use ("a level 1+ spell slot", "1 Superiority Die"). */
  restore?: string
}

export type Dnd5eActivation = 'action' | 'bonus' | 'reaction' | 'free' | 'magic' | 'special'

/** A saving throw an effect forces. `dc`: `spell` (your spell save DC) or `8+PB+<ABL>`. */
export interface Dnd5eSave {
  ability: Dnd5eAbility
  dc: 'spell' | `8+PB+${Dnd5eAbility}` | `8+PB+${Dnd5eAbility}/${Dnd5eAbility}` | number
}

/**
 * Something a feature, trait or feat gives outright. Values use the book's names
 * ("Athletics", "Martial weapons", "Fire", "Darkvision").
 */
export type Dnd5eGrant =
  | {
      kind: 'skill' | 'expertise' | 'save' | 'armor' | 'weapon' | 'tool' | 'language'
      value: string
    }
  | { kind: 'resistance' | 'immunity' | 'conditionImmunity'; value: string }
  | { kind: 'sense'; value: string; range: number }
  /** A speed set to `amount` feet (or equal to your walking Speed), or raised by `bonus` feet. */
  | {
      kind: 'speed'
      value: 'walk' | 'fly' | 'swim' | 'climb' | 'burrow'
      amount?: number | 'walk'
      bonus?: number
    }
  /**
   * A spell you always have prepared or know; `at` is the character or class level it arrives,
   * `free` its casts without a slot, `atWill` when it costs no slot at all (Armor of Shadows).
   */
  | { kind: 'spell'; spell: string; at?: number; free?: Dnd5eUses; atWill?: boolean }
  | { kind: 'hp'; perLevel: number }
  | { kind: 'ac'; formula: string }
  | { kind: 'feat'; feat: string }

/**
 * A pick the builder or level-up has to ask for. `from` lists the options by name (skills,
 * tools) or slug (spells, feats, options); `group` names an option group
 * (`Dnd5eOptionGroup.slug`, e.g. `eldritch-invocations`); `list` a class spell list;
 * `maxLevel` the highest spell level allowed.
 */
export interface Dnd5eChoice {
  kind:
    | 'skill'
    | 'expertise'
    | 'tool'
    | 'language'
    | 'cantrip'
    | 'spell'
    | 'feat'
    | 'ability'
    | 'weaponMastery'
    | 'option'
    | 'damageType'
  count: number
  from?: string[]
  group?: string
  list?: string
  maxLevel?: number
  /** Feats: the categories allowed. */
  category?: Dnd5eFeatCategory[]
  /** Spell picks narrowed to these schools, or to Ritual spells. */
  school?: Dnd5eSchool[]
  ritual?: boolean
  /** A limit fields can't state ("a Warlock cantrip that deals damage"). */
  note?: string
  /** A label for the pick ("Divine Order", "Draconic Ancestor"). */
  label?: string
  /**
   * When the count grows with level: the class table column that holds it (`Plans Known`,
   * `Eldritch Invocations`); `count` is then the level-1 (or first) value.
   */
  column?: string
}

/** The mechanics of a feature, trait, feat benefit or option, as far as they can be fields. */
export interface Dnd5eMechanics {
  activation?: Dnd5eActivation
  uses?: Dnd5eUses
  /** Dice it rolls: `1d10`, `2d6`, or `column:<name>` (Martial Arts, Sneak Attack). */
  dice?: string
  damageType?: string
  save?: Dnd5eSave
  /** Feet, or "Self", "Touch". */
  range?: number | string
  duration?: string
  grants?: Dnd5eGrant[]
  choices?: Dnd5eChoice[]
  /** Named options inside the feature (Divine Order's Protector and Thaumaturge). */
  options?: Dnd5eOption[]
}

export interface Dnd5eOption extends Dnd5eMechanics {
  name: string
  /** SRD text or (non-SRD) a summary in Lantern's words. */
  text?: string
  summary?: string
}

/**
 * A class or subclass feature. One the class table lists again at a later level (Expertise at
 * 2 and 9, Metamagic at 2, 10 and 17, "Mystic Arcanum (Level 7 Spell)") grants its `choices`
 * again at each of those levels.
 */
export interface Dnd5eFeature extends Dnd5eMechanics {
  name: string
  level: number
  srd: boolean
  page?: number
  text?: string
  summary?: string
}

export type Dnd5eSpellcastingKind = 'full' | 'half' | 'third' | 'pact'

export interface Dnd5eSpellcasting {
  ability: Dnd5eAbility
  kind: Dnd5eSpellcastingKind
  /** The class whose spell list it uses (a Fighter's Eldritch Knight uses `wizard`). */
  list: string
  /** Per level 1–20 (index 0 = level 1); 0 before the feature starts. */
  cantrips: number[]
  prepared: number[]
  /** Slots per level 1–20, each 9 long (spell levels 1–9). Pact Magic leaves this out. */
  slots?: number[][]
  /** Pact Magic per level 1–20. */
  pact?: { slots: number; slotLevel: number }[]
  /** Spellcasting focus kinds ("Holy Symbol", "Arcane Focus"). */
  focus?: string
  ritual: boolean
}

export interface Dnd5eLevel {
  level: number
  proficiencyBonus: number
  /** Feature names as the class table prints them. */
  features: string[]
  /** The class table's other columns by their headers ("Rages", "Sneak Attack"). */
  columns: Record<string, string>
}

export interface Dnd5eClassDef extends Dnd5eRecord {
  hitDie: 6 | 8 | 10 | 12
  /** One of these (`or`) or all of them (`and`). */
  primaryAbility: { abilities: Dnd5eAbility[]; all: boolean }
  saves: Dnd5eAbility[]
  skills: { count: number; options: string[] }
  weapons: string[]
  armor: string[]
  tools: string[]
  toolChoice?: Dnd5eChoice
  /** Starting equipment options as printed ("(A) Greataxe, 4 Handaxes…"); the last is gold. */
  equipment: { option: string; items: string; gp: number }[]
  multiclass: {
    /** Ability scores of 13 or more needed (any of `any`). */
    prerequisite: { abilities: Dnd5eAbility[]; any: boolean }
    /** What a multiclass character gains from the Core Traits table. */
    gains: string
  }
  levels: Dnd5eLevel[]
  /** The table's extra column names, in order. */
  columns: string[]
  subclassLevel: number
  /** Levels with Ability Score Improvement (a feat). */
  asiLevels: number[]
  epicBoonLevel: number
  spellcasting?: Dnd5eSpellcasting
  features: Dnd5eFeature[]
  /** Option groups the class picks from (`eldritch-invocations`, `metamagic`, `plans`). */
  optionGroups: string[]
}

export interface Dnd5eSubclassDef extends Dnd5eRecord {
  /** The class slug. */
  class: string
  features: Dnd5eFeature[]
  /**
   * Spells always prepared, by class level (a Life Domain's). `group`: the option they belong
   * to when the subclass has several lists (a Circle of the Land's "Arid Land").
   */
  spells?: { level: number; spells: string[]; group?: string }[]
  /** Subclass casting (Eldritch Knight, Arcane Trickster). */
  spellcasting?: Dnd5eSpellcasting
  optionGroups: string[]
}

export type Dnd5eSize = 'Tiny' | 'Small' | 'Medium' | 'Large'

export interface Dnd5eSpeciesTrait extends Dnd5eMechanics {
  name: string
  /** Character level it arrives (Draconic Flight at 5); 1 when absent. */
  level?: number
  text?: string
  summary?: string
}

/** A lineage, legacy or ancestry inside a species (High Elf, Infernal, Red dragon). */
export interface Dnd5eLineage extends Dnd5eMechanics {
  name: string
  text?: string
  summary?: string
  /** Spells by character level (1, 3, 5), always prepared. */
  spells?: { level: number; spell: string }[]
}

export interface Dnd5eSpeciesDef extends Dnd5eRecord {
  creatureType: string
  sizes: Dnd5eSize[]
  sizeText: string
  speed: number
  traits: Dnd5eSpeciesTrait[]
  /** The pick the species asks for (Elven Lineage, Draconic Ancestry), with its options. */
  lineages?: { label: string; options: Dnd5eLineage[]; spellAbility?: Dnd5eAbility[] }
}

export interface Dnd5eBackgroundDef extends Dnd5eRecord {
  /** The three ability scores: +2/+1 to two of them, or +1 to all three. */
  abilities: Dnd5eAbility[]
  /** The Origin feat's slug, and the option it fixes ("Cleric" for Magic Initiate). */
  feat: { slug: string; option?: string }
  /**
   * When the book lets the player take any feat of a category instead ("Survivor or a Dark Gift
   * feat of your choice"): `feat` is then the named or recommended one.
   */
  featChoice?: Dnd5eChoice
  skills: string[]
  tool?: string
  toolChoice?: Dnd5eChoice
  equipment: { option: string; items: string; gp: number }[]
}

export type Dnd5eFeatCategory =
  | 'origin'
  | 'general'
  | 'fighting-style'
  | 'epic-boon'
  /** Eberron's Dragonmark feats (Forge of the Artificer), taken like an Origin feat. */
  | 'dragonmark'
  /** D&D Beyond Drops' Planar Pact feats. */
  | 'planar-pact'
  /** Ravenloft's Dark Gifts. */
  | 'dark-gift'

/** A feat prerequisite as fields, with the book's line beside it for display. */
export interface Dnd5ePrerequisite {
  text: string
  level?: number
  /** Ability scores of 13+ (or `min`): one of them when `any`. */
  abilities?: { abilities: Dnd5eAbility[]; min: number; any: boolean }
  species?: string[]
  /** Class slugs (levels in that class). */
  classes?: string[]
  spellcasting?: boolean
  /** A feature or training it needs ("Fighting Style Feature", "Medium Armor Training"). */
  feature?: string
}

export interface Dnd5eFeatDef extends Dnd5eRecord, Dnd5eMechanics {
  category: Dnd5eFeatCategory
  prerequisite?: Dnd5ePrerequisite
  repeatable: boolean
  /** "Ability Score Increase": +`amount` to one of `abilities`, up to `max`. */
  asi?: { abilities: Dnd5eAbility[]; amount: number; max: number; choose?: number }
  /** Named benefits ("Initiative Proficiency", "Initiative Swap"). */
  benefits: Dnd5eOption[]
}

export type Dnd5eSchool =
  | 'Abjuration'
  | 'Conjuration'
  | 'Divination'
  | 'Enchantment'
  | 'Evocation'
  | 'Illusion'
  | 'Necromancy'
  | 'Transmutation'

export interface Dnd5eSpellDef extends Dnd5eRecord {
  /** 0 for a cantrip. */
  level: number
  school: Dnd5eSchool
  /** Class slugs whose spell list has it. */
  classes: string[]
  /**
   * Other lists that have it, as the book names them: a subclass's own list ("Paladin (Death
   * Knight)") or a lineage's ("Void Elf").
   */
  extraLists?: string[]
  castingTime: string
  activation: Dnd5eActivation | 'time'
  ritual: boolean
  /** "Reaction, which you take when…": the trigger. */
  trigger?: string
  range: string
  components: { v: boolean; s: boolean; m?: string; cost?: number; consumed?: boolean }
  duration: string
  concentration: boolean
  /** "Using a Higher-Level Spell Slot" or "Cantrip Upgrade": SRD text, or a summary. */
  higherLevel?: string
  attack?: 'melee' | 'ranged'
  save?: Dnd5eAbility
  /** Damage dice and types the spell states, in order. */
  damage?: { dice: string; type: string }[]
  /** Healing dice ("2d8"). */
  healing?: string
  /** Dice added per slot level above the spell's, or per cantrip tier. */
  scaling?: { kind: 'slot' | 'cantrip'; dice?: string }
}

export type Dnd5eOptionGroupKind =
  | 'eldritch-invocations'
  | 'metamagic'
  | 'maneuvers'
  | 'plans'
  | 'other'

/** A list a class or subclass picks from: invocations, metamagic, maneuvers, artificer plans. */
export interface Dnd5eOptionGroup {
  slug: string
  name: string
  /** The class (and subclass) that picks from it. */
  class: string
  subclass?: string
  entries: Dnd5eOptionEntry[]
}

export interface Dnd5eOptionEntry extends Dnd5eRecord, Dnd5eMechanics {
  prerequisite?: Dnd5ePrerequisite
  repeatable: boolean
  /** Sorcery points and the like ("2 Sorcery Points", "1 Superiority Die"). */
  cost?: string
}

export type Dnd5eWeaponProperty =
  | 'Ammunition'
  | 'Finesse'
  | 'Heavy'
  | 'Light'
  | 'Loading'
  | 'Range'
  | 'Reach'
  | 'Thrown'
  | 'Two-Handed'
  | 'Versatile'

export type Dnd5eMastery = 'Cleave' | 'Graze' | 'Nick' | 'Push' | 'Sap' | 'Slow' | 'Topple' | 'Vex'

export interface Dnd5eWeaponDef extends Dnd5eRecord {
  category: 'Simple' | 'Martial'
  type: 'Melee' | 'Ranged'
  damage: string
  damageType: string
  properties: Dnd5eWeaponProperty[]
  /** Properties as printed ("Thrown (Range 20/60)", "Versatile (1d8)"). */
  propertyText: string[]
  versatile?: string
  range?: { normal: number; long: number }
  ammunition?: string
  mastery: Dnd5eMastery
  weight: number
  /** Cost in copper pieces. */
  cost: number
}

export interface Dnd5eArmorDef extends Dnd5eRecord {
  category: 'Light' | 'Medium' | 'Heavy' | 'Shield'
  /** Base AC (or +2 for a shield). */
  ac: number
  /** How Dexterity adds: all, up to 2, or none. */
  dex: 'full' | 'max2' | 'none'
  strength?: number
  stealthDisadvantage: boolean
  weight: number
  cost: number
  don: string
  doff: string
}

export interface Dnd5eGearDef extends Dnd5eRecord {
  kind: 'gear' | 'tool' | 'pack' | 'ammunition' | 'focus' | 'mount' | 'vehicle'
  cost: number
  weight?: number
  /** Tools: the ability their checks use and what they craft. */
  ability?: Dnd5eAbility
  craft?: string[]
}

export interface Dnd5eMagicItemDef extends Dnd5eRecord {
  category: string
  rarity: string
  attunement: boolean
  /** Who may attune ("by a Wizard"). */
  attunementBy?: string
}

export interface Dnd5eConditionDef extends Dnd5eRecord {
  /** Each effect as a short bullet of the SRD text. */
  effects: string[]
}

export interface Dnd5eMasteryDef extends Dnd5eRecord {
  name: Dnd5eMastery
}
